import math

def is_square(n):
    if n < 0:
        return False
    if n == 0:
        return True
    s = int(math.isqrt(n))
    return s * s == n

def test_polynomial(P, n_range=[-10, 10]):
    results = {}
    for n in range(n_range[0], n_range[1] + 1):
        P_n = P(n)
        is_sq = is_square(P_n)
        results[n] = is_sq
    return results

# --- Test Case 1: P(x) = x^3 + k ---
print("--- Testing P(x) = x^3 + k ---")
for k in range(-10, 11):
    def P_k(x):
        return x**3 + k
    results = test_polynomial(P_k)

    # Print only interesting cases for brevity, or check for too many squares
    square_count = sum(results.values())
    if square_count == 0:
        print(f"P(x) = x^3 + {k}: No squares found in [-10, 10].")
    elif square_count > 2:
        print(f"P(x) = x^3 + {k}: {square_count} squares found. (N={list(results.keys())[next(i for i, v in enumerate(results.values()) if v)]} is a square)")
    elif square_count == 2:
        print(f"P(x) = x^3 + {k}: Exactly 2 squares found! Squares at n={[n for n, sq in results.items() if sq]}.")

