def prime_factorization(n):
    factors = {}
    d = 3
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                count += 1
                temp //= d
            factors[d] = count
        d += 2
    if temp > 1:
        factors[temp] = 1
    return factors

N = 12295801
factors = prime_factorization(N)
print(f"Prime factorization of {N}: {factors}")

